<script setup lang="ts">
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import PageHeader from '../components/PageHeader.vue'
import TemplatePdfPreview from '../components/TemplatePdfPreview.vue'
import { api } from '../lib/api'
import { toast } from '../lib/toast'
import type { Template, TemplateKind } from '../lib/types'

const route=useRoute(), router=useRouter(); const item=ref<Template|null>(null); const loading=ref(true), saving=ref(false), replacing=ref(false), deleting=ref(false), confirmDelete=ref(false), error=ref(''), notice=ref(''); const replacement=ref<File|null>(null), replacementEntry=ref(''); let pollTimer=0
const form=reactive({name:'',kind:'resume' as TemplateKind,description:''})
async function load(){try{item.value=await api.getTemplate(String(route.params.templateId));Object.assign(form,{name:item.value.name,kind:item.value.kind,description:item.value.description||''})}catch(cause){error.value=cause instanceof Error?cause.message:'Could not load the template.'}finally{loading.value=false}}
async function save(){if(!item.value)return;saving.value=true;try{item.value=await api.updateTemplate(item.value.id,{...form});toast.success('Template details saved.')}catch(cause){error.value=cause instanceof Error?cause.message:'Could not save the template.'}finally{saving.value=false}}
async function download(){if(!item.value)return;try{await api.downloadTemplate(item.value)}catch(cause){error.value=cause instanceof Error?cause.message:'Could not download the template.'}}
async function remove(){if(!item.value)return;deleting.value=true;try{await api.deleteTemplate(item.value.id);toast.success('Template deleted.');await router.push('/templates')}catch(cause){error.value=cause instanceof Error?cause.message:'Could not delete the template.';deleting.value=false}}
function selectReplacement(event:Event){replacement.value=(event.target as HTMLInputElement).files?.[0]||null;if(!replacement.value?.name.toLowerCase().endsWith('.zip'))replacementEntry.value=''}
async function pollProcessing(){if(!item.value||!['staged','queued'].includes(item.value.state))return;pollTimer=window.setTimeout(async()=>{try{item.value=await api.getTemplate(item.value!.id);if(item.value.state==='ready')toast.success('Source updated and PDF preview generated.');else await pollProcessing()}catch{await pollProcessing()}},1500)}
async function replaceSource(){if(!item.value||!replacement.value)return;replacing.value=true;error.value='';try{const staged=await api.stageTemplateSource(item.value.id,replacement.value,replacementEntry.value);await api.putStagedTemplate(staged.target,replacement.value);item.value=await api.completeTemplate(item.value.id);replacement.value=null;replacementEntry.value='';toast.info('Source uploaded. Extracting content and generating the PDF preview…');await pollProcessing()}catch(cause){error.value=cause instanceof Error?cause.message:'Could not replace the template source.'}finally{replacing.value=false}}
onMounted(load)
onBeforeUnmount(()=>window.clearTimeout(pollTimer))
</script>
<template><div class="page template-page"><PageHeader :title="item?.name || 'Template'" description="Preview the template as PDF, review its extracted source text, and maintain the metadata used during generation."><RouterLink class="button" to="/templates">Back to templates</RouterLink></PageHeader><p v-if="error" class="notice error">{{ error }}</p><p v-if="notice" class="notice">{{ notice }}</p><div v-if="loading" class="empty-state">Loading template…</div><template v-else-if="item"><section class="panel detail-heading"><div><span class="status-pill">{{ item.builtIn?'Built in':item.state.replaceAll('_',' ') }}</span><p>{{ item.format==='latex'?'LaTeX':item.format.toUpperCase() }} · {{ item.sourceName }}<template v-if="item.entryFile"> · Entry: {{ item.entryFile }}</template></p></div><button v-if="item.state==='ready'" class="button primary" type="button" @click="download">Download file</button></section><section v-if="item.builtIn" class="panel attribution"><h2>Attribution</h2><p>Created by {{ item.authorName }} · {{ item.license }} license · <a :href="item.sourceUrl" target="_blank" rel="noreferrer">View the original Overleaf template ↗</a></p></section><form v-if="!item.builtIn" class="panel form-grid" @submit.prevent="save"><label><span>Name</span><input v-model="form.name" required maxlength="120" /></label><label><span>Document type</span><select v-model="form.kind"><option value="resume">Resume</option><option value="cover_letter">Cover letter</option></select></label><label class="full"><span>Description</span><textarea v-model="form.description" maxlength="1000" rows="3" /></label><div class="full source-replacement"><div><strong>Source file</strong><p>Replacing the source regenerates its extracted text and stored PDF preview.</p></div><input type="file" accept=".tex,.zip,.doc,.docx" @change="selectReplacement" /><input v-if="replacement?.name.toLowerCase().endsWith('.zip')" v-model="replacementEntry" maxlength="300" placeholder="Entry file (optional), e.g. main.tex" /><button class="button" type="button" :disabled="!replacement||replacing" @click="replaceSource">{{ replacing?'Uploading…':'Replace source' }}</button></div><div class="full form-actions"><button class="text-button danger-text" type="button" @click="confirmDelete=true">Delete template</button><button class="button primary" :disabled="saving">{{ saving?'Saving…':'Save details' }}</button></div></form><section class="panel preview-panel"><div class="section-title"><div><p class="eyebrow">Unified preview</p><h2>PDF preview</h2></div><small>Stored when the source {{ item.format==='latex'?'TeX':item.format.toUpperCase() }} file is processed</small></div><TemplatePdfPreview v-if="item.state==='ready'" :template-id="item.id" /><div v-else class="empty-state compact">The preview becomes available when template processing is complete.</div></section><details class="panel source-section"><summary>Extracted template text</summary><p v-if="item.errorMessage" class="notice error">{{ item.errorMessage }}</p><pre v-if="item.content" class="source-preview">{{ item.content }}</pre><div v-else class="empty-state compact">{{ item.state==='queued'?'Scanning, extracting, and generating a PDF preview…':'No extracted text is available.' }}</div></details></template><ConfirmDialog :open="confirmDelete" title="Delete template?" :message="`“${item?.name ?? 'This template'}” and its stored source will be removed. This action cannot be undone.`" :busy="deleting" @cancel="confirmDelete=false" @confirm="remove" /></div></template>
<style scoped>.template-page{display:grid;gap:1rem}.detail-heading{display:flex;justify-content:space-between;align-items:center}.detail-heading p{margin:.7rem 0 0;color:var(--muted)}.attribution p{margin:0;color:var(--muted)}.attribution a{color:var(--accent);font-weight:700}.source-replacement{display:flex;align-items:center;gap:1rem;padding:1rem;border:1px solid var(--line);border-radius:10px;background:var(--surface-soft)}.source-replacement div{margin-right:auto}.source-replacement p{margin:.3rem 0 0;color:var(--muted);font-size:.9rem}.form-actions{justify-content:space-between}.danger-text{color:var(--danger)}.preview-panel{display:grid;gap:1rem}.section-title{display:flex;align-items:end;justify-content:space-between;gap:1rem}.section-title h2,.section-title p{margin-bottom:0}.section-title small{color:var(--muted)}.source-section summary{cursor:pointer;color:var(--ink);font-size:1.1rem;font-weight:700}.source-section[open] summary{margin-bottom:1rem}.source-preview{max-height:620px;overflow:auto;padding:1rem;border-radius:10px;background:var(--surface-soft);white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.empty-state.compact{padding:2rem}@media(max-width:760px){.source-replacement{align-items:stretch;flex-direction:column}.source-replacement div{margin-right:0}.section-title{align-items:flex-start;flex-direction:column}}</style>
